QByteArray fileHash(QString path){QFile f(path);check(f.open(QIODevice::ReadOnly),"hash open");return QCryptographicHash::hash(f.readAll(),QCryptographicHash::Sha256);}
QJsonObject input(QString id,QString date){return {{"meta",QJsonObject{{"instrumentId",id},{"code",id.section(':',2)},{"sourceId","fixture-authorized-indicative"},{"auctionFieldContractVerified",true},{"auctionTimestampMeaning","source-event"},{"volumeUnit","shares"},{"priceUnit","CNY"}}},{"phase","opening"},{"date",date},{"asOf",date+"T09:25:00+08:00"},{"baseline",10},{"baselineAvailableAt",date+"T09:14:00+08:00"},{"rows",QJsonArray{QJsonObject{{"time",date+"T09:24:00+08:00"},{"availableAt",date+"T09:24:00+08:00"},{"auctionReferencePrice",10.1},{"auctionMatchedVolume",100},{"auctionUnmatchedBuyVolume",10},{"auctionUnmatchedSellVolume",0}}}},{"history",QJsonArray{QJsonObject{{"instrumentId",id},{"unknownOriginalField","原历史不筛选、不合成"}}}},{"untouchedBody",QString::fromUtf8("原始正文🧪").repeated(30000)}};}
int main(int argc,char**argv){QCoreApplication a(argc,argv);try{
 QTemporaryDir temp;QString db=temp.filePath("market-v1.sqlite"),id="SH:stock:600000";auto raw=input(id,"2026-10-13");auto parsed=marketdata::auction(raw,id,QDateTime::fromString(raw["asOf"].toString(),Qt::ISODate));QJsonArray roster{QJsonObject{{"id",id},{"symbol","sh600000"},{"name","fixture name"},{"auctionOpeningMeta",parsed}}};
 auto missing=auctionHistorySource::collect(db,roster);check(missing["snapshots"].toArray().size()==1&&missing["state"]=="missing-database"&&!QFile::exists(db),"missing no creation; actual current retained");
 MarketStore store(db);auto saved=store.save("sh600000-auctionOpening",parsed);auto row=roster[0].toObject();row["auctionOpeningMeta"]=saved;roster[0]=row;auto before=fileHash(db);auto collected=auctionHistorySource::collect(db,roster);check(fileHash(db)==before,"readonly database byte invariant");auto snapshots=collected["snapshots"].toArray();if(snapshots.size()!=1||collected["duplicates"].toInt()!=2)fprintf(stderr,"%s\n",QJsonDocument(QJsonObject{{"state",collected["state"]},{"reason",collected["reason"]},{"diagnostics",collected["diagnostics"]},{"duplicates",collected["duplicates"]},{"archives",collected["archiveRowsVisited"]},{"caches",collected["cacheRowsVisited"]},{"origin",snapshots.isEmpty()?QJsonValue():snapshots.first().toObject()["origins"]}}).toJson(QJsonDocument::Compact).constData());check(snapshots.size()==1&&collected["duplicates"].toInt()==2,"archive cache memory content dedup");auto snapshot=snapshots.first().toObject();check(snapshot["id"].toString().contains(saved["seriesKey"].toString()),"real archive identity");check(snapshot["input"].toObject()==raw&&snapshot["coverage"].toObject()["cacheKey"]=="sh600000-auctionOpening","complete original history/body and actual metadata");
 // More than one internal page; actual MarketStore creates daily series archives.
 // Older saves do not replace the latest cache: insert exact archive schema fixtures separately.
 {auto conn=QSqlDatabase::addDatabase("QSQLITE","auction-history-fixture");conn.setDatabaseName(db);check(conn.open(),"fixture db");QSqlQuery q(conn);for(int n=0;n<260;n++){QString date=QDate(2025,1,1).addDays(n).toString(Qt::ISODate);auto r=input(id,date);r.remove("untouchedBody");auto p=marketdata::auction(r,id,QDateTime::fromString(r["asOf"].toString(),Qt::ISODate));QString key=QString("fixture-series-%1").arg(n,4,10,QChar('0'));p.remove("rows");p["seriesKey"]=key;p["cacheKey"]="sh600000-auctionOpening";q.prepare("INSERT INTO series(series_key,metadata) VALUES(?,?)");q.addBindValue(key);q.addBindValue(QString::fromUtf8(QJsonDocument(p).toJson(QJsonDocument::Compact)));check(q.exec(),"archive fixture insert");}conn.close();}QSqlDatabase::removeDatabase("auction-history-fixture");
 {auto conn=QSqlDatabase::addDatabase("QSQLITE","auction-history-filter-fixture");conn.setDatabaseName(db);check(conn.open(),"filter fixture db");QSqlQuery q(conn);QList<QPair<QString,QString>> unrelated{{"fixture-non-auction",QString::fromUtf8(QJsonDocument(QJsonObject{{"cacheKey","sh600000-day"},{"nested",QJsonObject{{"cacheKey","sh600000-auctionOpening"}}},{"largeBody",raw["untouchedBody"]}}).toJson(QJsonDocument::Compact))},{"fixture-other-symbol","{\"cacheKey\":\"sz600000-auctionOpening\",\"rawInput\":{}}"},{"fixture-corrupt-unrelated","not-json"},{"fixture-key-substring","{\"cacheKey\":\"sh600000-auctionOpening-other\"}"}};for(auto item:unrelated){q.prepare("INSERT INTO series(series_key,metadata) VALUES(?,?)");q.addBindValue(item.first);q.addBindValue(item.second);check(q.exec(),"unrelated metadata fixture");}conn.close();}QSqlDatabase::removeDatabase("auction-history-filter-fixture");
 before=fileHash(db);auto all=auctionHistorySource::collect(db,roster);check(all["archiveRowsVisited"].toInt()==261&&all["snapshots"].toArray().size()==261,"all exact auction keyset pages no first-N cutoff");check(all["state"]=="complete"&&all["diagnostics"].toArray().isEmpty(),"SQL JSON capability/exact top-level filter excludes unrelated large/corrupt/substrings before body read");check(fileHash(db)==before,"multi-page readonly bytes");
 auto other=auctionHistorySource::collect(db,QJsonArray{QJsonObject{{"id","BJ:stock:600000"},{"symbol","bj600000"},{"name","fixture name"}}});check(other["snapshots"].toArray().isEmpty()&&other["archiveRowsVisited"].toInt()==0,"no name/bare code cross identity or unrelated archive body read");
 auto quote=row;auto ordinary=parsed;ordinary["rawInput"]=QJsonObject{{"meta",QJsonObject{{"instrumentId",id},{"code","600000"},{"sourceId","sina-quote"}}}};quote["auctionOpeningMeta"]=ordinary;auto none=auctionHistorySource::collect(temp.filePath("absent/market-v1.sqlite"),QJsonArray{quote});check(none["snapshots"].toArray().isEmpty(),"ordinary never indicative");
 auto typed=parsed;auto typedRaw=raw;auto typedMeta=typedRaw["meta"].toObject();typedMeta["instrumentId"]="SH:etf:600000";typedRaw["meta"]=typedMeta;typed["rawInput"]=typedRaw;auto typedInstrument=roster[0].toObject();typedInstrument["auctionOpeningMeta"]=typed;check(auctionHistorySource::collect(temp.filePath("absent/market-v1.sqlite"),QJsonArray{typedInstrument})["snapshots"].toArray().isEmpty(),"same market/code stock ETF distinct");
 auto closing=raw;closing["phase"]="closing";closing["asOf"]="2026-10-13T15:00:00+08:00";auto closingPoint=closing["rows"].toArray().first().toObject();closingPoint["time"]="2026-10-13T14:59:00+08:00";closingPoint["availableAt"]="2026-10-13T14:59:00+08:00";closing["rows"]=QJsonArray{closingPoint};auto closingParsed=marketdata::auction(closing,id,QDateTime::fromString(closing["asOf"].toString(),Qt::ISODate));store.save("sh600000-auctionClosing",closingParsed);before=fileHash(db);auto both=auctionHistorySource::collect(db,roster);check(both["snapshots"].toArray().size()==262&&fileHash(db)==before,"both exact opening closing cache keys");
 QTemporaryDir foreignDir;QString foreign=foreignDir.filePath("market-v1.sqlite");{QFile f(foreign);f.open(QIODevice::WriteOnly);f.write("foreign-not-sqlite");}before=fileHash(foreign);auto refusal=auctionHistorySource::collect(foreign,QJsonArray());check(refusal["state"]=="foreign-database"&&fileHash(foreign)==before,"foreign readonly refusal");
 QTemporaryDir emptyDir;QString empty=emptyDir.filePath("market-v1.sqlite");{auto conn=QSqlDatabase::addDatabase("QSQLITE","auction-history-empty");conn.setDatabaseName(empty);check(conn.open(),"empty fixture db");QSqlQuery q(conn);check(q.exec("PRAGMA user_version=0"),"empty version");conn.close();}QSqlDatabase::removeDatabase("auction-history-empty");before=fileHash(empty);auto absentTables=auctionHistorySource::collect(empty,QJsonArray());check(absentTables["state"]=="missing-native-tables"&&absentTables["snapshots"].toArray().isEmpty()&&fileHash(empty)==before,"missing old tables no creation");
 {auto conn=QSqlDatabase::addDatabase("QSQLITE","auction-history-foreign-schema");conn.setDatabaseName(empty);check(conn.open(),"foreign fixture db");QSqlQuery q(conn);check(q.exec("CREATE TABLE business_records(id TEXT)"),"foreign table fixture");conn.close();}QSqlDatabase::removeDatabase("auction-history-foreign-schema");before=fileHash(empty);check(auctionHistorySource::collect(empty,QJsonArray())["state"]=="foreign-database"&&fileHash(empty)==before,"foreign business schema not scanned or migrated");
 if(argc>1){QFile golden(argv[1]);check(golden.open(QIODevice::WriteOnly),"owned fixture output");golden.write(QJsonDocument(QJsonObject{{"fixtureOnly",true},{"input",raw},{"metadata",parsed},{"expectedSha256",snapshot["contentSha256"]}}).toJson(QJsonDocument::Compact));}
 puts("PASS auction history actual MarketStore/raw contract/read-only/full body/keyset/dedup/cross identity/ordinary/foreign; fixture-only");return 0;
 }catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
